// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Proxy {
    /// @notice Implementation contract address (storage slot 0)
    address private implementation;

    /// @dev Fallback function - delegates all calls to implementation
    fallback() external payable {
        // Special getter: returns implementation address
        if (msg.sig == 0xa619486e) {
            assembly {
                mstore(0, sload(0))
                return(0, 32)
            }
        }

        // Delegate call to implementation contract
        assembly {
            // Copy entire calldata to memory starting at position 0
            calldatacopy(0, 0, calldatasize())

            // Delegate call: preserves msg.sender and msg.value
            let success := delegatecall(
                gas(),                    // forward all gas
                sload(0),                 // implementation address (slot 0)
                0,                        // input data offset in memory
                calldatasize(),           // input data length
                0,                        // output data offset in memory
                0                         // output data length (will be set by call)
            )

            // Copy return data from the delegate call
            returndatacopy(0, 0, returndatasize())

            // Revert if delegatecall failed, otherwise return data
            switch success
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    /// @dev Receive function for plain ETH transfers
    receive() external payable {}
}
```

## Key Observations

| Component | Description |
|-----------|-------------|
| **Storage Slot 0** | Holds the implementation contract address |
| **Function `0xa619486e`** | Returns the implementation address (getter) |
| **Fallback** | Delegates all other calls via `delegatecall` |
| **Payable** | Accepts ETH and forwards it to implementation |

## Architecture Pattern

This is a **transparent proxy** design where:
1. All logic lives in the `implementation` contract
2. This contract only stores the address and delegates calls
3. The special selector `0xa619486e` allows reading the implementation address directly

This pattern is commonly used for **upgradeable contracts** where the implementation can be swapped while preserving storage and contract address.

